// Pega o primeiro PDF enviado no formulário e padroniza o nome do binário
const item = $input.first();
const chaves = Object.keys(item.binary || {});
if (chaves.length === 0) {
  throw new Error('Nenhum PDF recebido.');
}
return [{ json: {}, binary: { data: item.binary[chaves[0]] } }];

const EXIGENCIAS = {
  "programa": "Auxílio Moradia Temporário (programa fictício, para demonstração)",
  "exigencias": [
    {
      "id": "R1",
      "documento": "Documento de identidade do responsável familiar (RG ou CNH)",
      "regra": "Edital fictício, item 4.1"
    },
    {
      "id": "R2",
      "documento": "CPF do responsável familiar",
      "regra": "Edital fictício, item 4.1"
    },
    {
      "id": "R3",
      "documento": "Comprovante de residência no município emitido há no máximo 90 dias",
      "regra": "Edital fictício, item 4.2"
    },
    {
      "id": "R4",
      "documento": "Comprovante de renda de todos os membros da família, ou declaração de ausência de renda",
      "regra": "Edital fictício, item 4.3"
    },
    {
      "id": "R5",
      "documento": "Renda familiar per capita de até meio salário mínimo",
      "regra": "Edital fictício, item 3.1"
    },
    {
      "id": "R6",
      "documento": "Laudo ou relatório social que comprove a situação de vulnerabilidade",
      "regra": "Edital fictício, item 4.4"
    },
    {
      "id": "R7",
      "documento": "Contrato de locação ou declaração do locador com valor do aluguel",
      "regra": "Edital fictício, item 4.5"
    },
    {
      "id": "R8",
      "documento": "Certidão negativa de propriedade de imóvel em nome dos membros da família",
      "regra": "Edital fictício, item 4.6",
      "observacao": "Certidão positiva com efeito de negativa é aceita."
    }
  ]
};

const texto = ($json.text || '').slice(0, 150000);
const prompt =
  `Você é analista de controle interno. Programa: ${EXIGENCIAS.programa}.\n` +
  'Confira o processo contra CADA exigência abaixo e chame a ferramenta registrar_analise com uma linha por exigência.\n' +
  "Use 'Atendido' só com evidência clara no texto; 'Pendente' quando o documento falta ou contraria a regra; " +
  "'Verificar' quando há dúvida. Nunca invente conteúdo que não está no processo.\n\n" +
  `<exigencias>\n${JSON.stringify(EXIGENCIAS.exigencias, null, 1)}\n</exigencias>\n\n` +
  `<processo>\n${texto || '[PDF sem texto extraível — pode ser imagem escaneada]'}\n</processo>`;

const body = {
  model: 'claude-sonnet-5-5',
  max_tokens: 4000,
  tools: [{
    name: 'registrar_analise',
    description: 'Registra o resultado da análise, uma linha por exigência.',
    input_schema: {
      type: 'object',
      properties: {
        itens: { type: 'array', items: { type: 'object', properties: {
          id: { type: 'string' },
          status: { type: 'string', enum: ['Atendido', 'Pendente', 'Verificar'] },
          evidencia: { type: 'string' }
        }, required: ['id', 'status', 'evidencia'] } },
        resumo: { type: 'string' }
      },
      required: ['itens', 'resumo']
    }
  }],
  tool_choice: { type: 'tool', name: 'registrar_analise' },
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { body, exigencias: EXIGENCIAS.exigencias } }];

// Junta a resposta do Claude com a lista de exigências e monta o relatório
const exigencias = $('Montar pedido ao Claude').first().json.exigencias;
const conteudo = $json.content || [];
const chamada = conteudo.find(b => b.type === 'tool_use' && b.name === 'registrar_analise');
if (!chamada) {
  throw new Error('O modelo não devolveu a análise estruturada.');
}
const porId = Object.fromEntries((chamada.input.itens || []).map(i => [i.id, i]));
const VALIDOS = ['Atendido', 'Pendente', 'Verificar'];

const linhas = exigencias.map(ex => {
  const item = porId[ex.id] || { status: 'Verificar', evidencia: 'O modelo não analisou este item.' };
  // Item pulado ou status fora da lista nunca vira "Atendido"
  const status = VALIDOS.includes(item.status) ? item.status : 'Verificar';
  return { id: ex.id, exigencia: ex.documento, regra: ex.regra, status, evidencia: item.evidencia || '' };
});

const pendentes = linhas.filter(l => l.status !== 'Atendido').length;
const tabela = linhas.map(l => `${l.id} | ${l.status} | ${l.exigencia} | ${l.evidencia}`).join('\n');
const relatorio =
  `${pendentes} de ${linhas.length} exigências pendentes ou a verificar.\n\n` +
  `${tabela}\n\nResumo: ${chamada.input.resumo || ''}\n\n` +
  'A IA organiza a conferência; a decisão final é do analista.';

return [{ json: { pendentes, total: linhas.length, linhas, relatorio } }];
